class Solution {
public:
    int findPoisonedDuration(vector<int>& timeSeries, int duration) {
        int total = 0;
        for (int i = 0; i < (int)timeSeries.size(); i++) {
            if (i + 1 < (int)timeSeries.size()) total += min(duration, timeSeries[i + 1] - timeSeries[i]);
            else total += duration;
        }
        return total;
    }
};
